@log_input_and_output
def get_vm_hostname():
    """
    Gets VM hostname.

    :return: hostname of VM read via socket library
    :rtype: str
    :raises HostnameUnavailable if socket couldn't be read
    """
    try:
        return socket.gethostname()
    except socket.gaierror:
        raise HostnameUnavailable("Couldn't resolve VM hostname!")


def get_vm_ip_address():
    """
    Gets VM IP address.

    :return: IP address of VM read via socket library
    :rtype: str
    :raises HostIpAddressUnavailable if socket couldn't resolve VM IP address
    """
    try:
        return socket.gethostbyname(socket.gethostname())
    except socket.gaierror:
        raise HostIpAddressUnavailable("Couldn't resolve VM IP address!")


@log_input_and_output
def get_vm_password():
    """
    Gets VM password. The method works only if vncpasswd is the same as system password.
    Otherwise it's not possible to retrieve system password because of encryption.

    :return: password of VM read via os library from '/etc/ute/vncpasswd' file.
    :rtype: str

    :raises FileNotFoundError if file with vnc password was not found on VM.
    """
    vncpasswd_path = "/etc/ute/vncpasswd"

    if os.path.isfile(vncpasswd_path):
        try:
            process = os.popen(f"sudo cat {vncpasswd_path}")
            vncpasswd = process.read()
        finally:
            process.close()
    else:
        raise FileNotFoundError(f"File with vnc password was not found: '{vncpasswd_path}'")

    return vncpasswd


@log_input_and_output
def check_whether_vm_has_free_space(path, file_size):
    """
    Checks whether VM has enough free space to save file of given size under given path.

    :param path: path to directory where file should be saved, i.e. '/tmp'
    :type path: str
    :param file_size: file size in bytes
    :type file_size: int
    :return: True if there is enough free space, False otherwise
    :rtype: bool
    """
    disk_space = os.statvfs(path)
    free_space = (disk_space.f_bavail * disk_space.f_frsize)
    log_result("path: {} disk_space: {} free_space: {}".format(path, disk_space, free_space))
    return free_space > file_size


