@log_input_and_output
def compare_two_dicts(dict_1, dict_2):
    """
    Compares two dictionaries key by key and it's values.
    Dictionaries should be in form key [str] : values [list of strings].
    Input dictionaries should have the same number of keys.
    Values in the list must be strings.

    :param dict_1: first dictionary to compare
    :type dict_1: dict
    :param dict_2: second dictionary to compare
    :type dict_2: dict
    :raises KeyError if there will be no matching key in one of the dict.
    :raises ValueError if there will be element (or lack of element) that does not match in both dict
    values of specific key
    :return: True if dicts are equal
    :rtype: Boolean
    """
    dict_1 = _format_dict_keys_to_compare(dict_1)
    dict_2 = _format_dict_keys_to_compare(dict_2)
    try:
        if dict_1 == dict_2:
            return True
        else:
            for element in dict_1.keys():
                dict_1_values = _format_dict_values_to_compare(dict_1, element)
                dict_2_values = _format_dict_values_to_compare(dict_2, element)
                if dict_1_values == dict_2_values:
                    continue
                else:
                    _raise_exception_with_mismatching_values(dict_1_values, dict_2_values, element)
        return True
    except KeyError:
        _raise_exception_with_mismatching_keys(dict_1, dict_2)


@log_input_and_output
def get_dict_key_and_value_if_regex_matches_dict_value_from_list(list_data, value_regex):
    """
    Gets dictionary key and value if value matches regex from list containing dictionaries.

    :param list_data: list of dictionaries to be searched
    :type list_data: list
    :param value_regex: regex for dictionary keys
    :type value_regex: str
    :return: key and value from fist dictionary with matching regex
    :rtype: tuple(str, str) or None
    """
    for item in list_data:
        if isinstance(item, dict):
            pair = _get_dict_key_and_value_if_regex_matches_dict_value(item, value_regex)
            if pair:
                return pair
    return (None, None)


@log_input_and_output
def check_if_directory_with_log_is_not_empty(log_dir, name_of_log):
    """
    Checks whether directory with log is not empty.

    :param log_dir: path to dir with log
    :type log_dir: str
    :param name_of_log: name of log file to be checked
    :type name_of_log: str
    """
    files = os.listdir(log_dir)

    for _file in files:
        path_file = "{}/{}".format(log_dir, _file)
        is_file = os.path.isfile(path_file)
        get_size = os.path.getsize(path_file)

        if not is_file or get_size == 0:
            log_suppression("Empty {} collected".format(name_of_log))


