@log_input_and_output
def find_files_in_directory_by_regex(directory_path, regex, reverse_sort=False):
    """
    Gets file names of files located in a given directory path matching a particular regex pattern.

    :param directory_path: Path to directory with files
    :type directory_path: str
    :param regex: Filename regex to find
    :type regex: str
    :param reverse_sort: Flag to sort files in reverse order by modification time (default: False, meaning sorting from oldest to newest).
    :type reverse_sort: bool
    """
    files = [file for file in os.listdir(directory_path) if re.fullmatch(regex, file)]
    return sorted(files, key=lambda f: os.path.getmtime(os.path.join(directory_path, f)), reverse=reverse_sort)


@log_input_and_output
def combine_files_into_one(directory_path, file_names, new_file_name, combine_order='size_desc'):
    """
    Combines multiple files from a given directory into a new single file.
    Files are combined in the specified order based on the `combine_order` parameter.
    :param directory_path: path to directory with files
    :type directory_path: str
    :param file_names: list of file names to combine
    :type file_names: list
    :param new_file_name: name of the new file with extension e.g 'combined_file.xml'
    :type new_file_name: str
    :param combine_order: The order in which files are combined. Default 'size_desc'. Allowed options:
                          - 'modification_asc': Files are combined from the newest to the oldest based on modification time.
                          - 'modification_desc': Files are combined from the oldest to the newest based on modification time.
                          - 'size_asc': Files are combined from smallest to largest based on file size.
                          - 'size_desc': Files are combined from largest to smallest based on file size.
    :type combine_order: str
    """
    file_paths = [os.path.join(directory_path, file_name) for file_name in file_names]

    if 'size' in combine_order:
        file_paths.sort(key=os.path.getsize, reverse=('desc' in combine_order))
    elif 'modification' in combine_order:
        file_paths.sort(key=os.path.getmtime, reverse=('desc' in combine_order))

    combined_file_path = os.path.join(directory_path, new_file_name)
    with open(combined_file_path, 'w') as combined_file:
        for file_path in file_paths:
            with open(file_path, 'r') as file:
                lines = file.readlines()
                if combined_file.tell() > 0 and lines and not lines[0].startswith('\n'):
                    combined_file.write('\n')
                combined_file.writelines(lines)

    return new_file_name


