def extract_all_archives_from_path(regex_path: str) -> str:
    r"""
    Extracts all nested archives which names are included in provided regex path.
    Each archive is extracted to directory with the same name as the archive (but without file extension)
    i.e. /home/ute/snapshot.zip will be extracted to /home/ute/snapshot directory.
    Supported archive formats: zip, gz.
    :param regex_path: absolute path which includes all nested archives to be extracted;
                       each name used in this path (and separated by / char) is a regular expression which will be used to match names in file system;
                       i.e. r'/home/ute/snapshot\.zip/rcplog_[0-9]*\.zip' can be used to extract /home/ute/snapshot.zip/rcplog_20240422094529.zip;
    :type regex_path: str
    :return: path of extracted nested archives based on provided regex path;
             i.e. '/home/ute/snapshot/rcplog_20240422094529'
    :rtype: str
    :raises NameError: if any regex from path will not match with name from file system OR if it will match with more than one name
    """
    extracted_path = ''

    for regex_part in regex_path.split('/'):
        if not regex_part:
            continue

        matched_name = _match_names_from_dir_content_with_regex(dir_path=extracted_path, regex=regex_part)

        if matched_name.endswith('.zip'):
            extracted_path = _extract_zip(dir_path=extracted_path, archive_name=matched_name)
        elif matched_name.endswith('.gz'):
            extracted_path = _extract_gz(dir_path=extracted_path, archive_name=matched_name)
        else:
            extracted_path = f'{extracted_path}/{matched_name}'

    return extracted_path


def show_virtual_environment():
    """
    Executes pip freeze on the VM to list all installed libraries and their versions.
    """
    result = subprocess.run(
        [sys.executable, "-m", "pip", "freeze"],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=True
    )

    if result.stderr:
        log_warning(f'Error occurred while fetching virtual environment details: {result.stderr}')
    log_env_state(f'Python version: {python_version()}\n'
                  f'Virtual environment content:\n' + '\n'.join(result.stdout.splitlines()))


