@log_input_and_output
def find_file_and_get_filepath(filename: str, root: str = '/') -> str or None:
    """
    Finds a file in the directory tree starting from the given root directory.
    If the file is found, returns its absolute path. Otherwise, returns None.
    :param filename: name of the file to find
    :type filename: str
    :param root: root directory to start searching from, default is '/'
    :type root: str
    :return: absolute path to the file if found, None otherwise
    :rtype: str or None
    """
    for dirpath, dirnames, filenames in os.walk(root):
        if filename in filenames:
            return os.path.join(dirpath, filename)
    return None


@log_input_and_output
def add_suffix_to_files_with_specific_extension(path, extension, suffix):
    """
    Adds suffixes to filenames with particular extension in whole directory.
    :param path: path to the existing directory
    :type path: str
    :param extension: extension of file i.e. '.LOG'
    :type extension: str
    :param suffix: suffix that will be added to filenames i.e. "13_08_2025_13:52:22"
    :type suffix: str
    """
    extension_length = len(extension)
    for file in os.listdir(path):
        if extension in file:
            os.rename(f'{path}/{file}', f'{path}/{file[0:(len(file)) - extension_length]}{suffix}{extension}')


@log_input_and_output
def extract_zip(dir_path: str, archive_name: str) -> str:
    """
    Extracts a zip archive to a directory with the same name as the archive (but without .zip extension).
    :param dir_path: path to the directory containing the zip archive
    :type dir_path: str
    :param archive_name: name of the zip archive to be extracted
    :type archive_name: str
    :return: path to the extracted archive
    :rtype: str
    """
    return _extract_zip(dir_path=dir_path, archive_name=archive_name)


@log_input_and_output
def _format_dict_keys_to_compare(dictie):
    return {k.replace(' ', ''): v for k, v in dictie.items()}


@log_input_and_output
def _format_dict_values_to_compare(dictie, element):
    return [d.replace(" ", "") for d in dictie[element]]


@log_input_and_output
def _raise_exception_with_mismatching_values(a_values, b_values, element):
    mismatching_values = set(a_values).symmetric_difference(set(b_values))
    raise ValueError("Key {0} does not have the same values. \n {1} are different".format(element,
                                                                                          list(mismatching_values)))


@log_input_and_output
def _raise_exception_with_mismatching_keys(a, b):
    diff_a = [k for k in a if k not in b]
    diff_b = [k for k in b if k not in a]
    mismatched_keys = diff_a + diff_b
    raise KeyError("Keys {0} are not present in both dictionaries, so dictionaries are not the same"
                   .format(mismatched_keys))


@log_input_and_output
def _get_path_to_this_package():
    return os.path.dirname(__file__)


@log_input_and_output
def _is_size_greater_than_zero_for_all_files(path_to_files):
    """
    Checks if for all files in directory size is grater than zero.
    :param path_to_files: path to directory with files to be checked
    :type path_to_files: str
    :return: True if for all files size is greater than zero, False otherwise
    :rtype: bool
    """
    file_list = [file for file in os.listdir(path_to_files) if os.path.isfile('{}/{}'.format(path_to_files, file))]
    if not file_list:
        raise DirectoryIsEmpty('Directory {} is empty'.format(path_to_files))
    for file in file_list:
        if not os.path.getsize('{}/{}'.format(path_to_files, file)) > 0:
            return False
    return True


@log_input_and_output
def _is_size_zero_for_all_files(path_to_files):
    """
    Checks if for all files in directory size is zero.
    :param path_to_files: path to directory with files to be checked
    :type path_to_files: str
    :return: True if for all files size is zero, False otherwise
    :rtype: bool
    """
    file_list = [file for file in os.listdir(path_to_files) if os.path.isfile('{}/{}'.format(path_to_files, file))]
    if not file_list:
        raise DirectoryIsEmpty('Directory {} is empty'.format(path_to_files))
    for file in file_list:
        if not os.path.getsize('{}/{}'.format(path_to_files, file)) == 0:
            return False
    return True


def _match_names_from_dir_content_with_regex(dir_path: str, regex: str) -> str:
    matched_names = []

    for name in os.listdir(dir_path if dir_path else '/'):
        if match(regex, name):
            matched_names.append(name)

    if len(matched_names) == 1:
        return matched_names[0]
    elif len(matched_names) > 1:
        raise NameError(f'Multiple directory or file names from {dir_path} directory are matching {regex} regex')
    elif len(matched_names) < 1:
        raise NameError(f'No directory nor file name from {dir_path} directory is matching {regex} regex')


def _extract_zip(dir_path: str, archive_name: str) -> str:
    archive_path = f'{dir_path}/{archive_name}'
    dir_name = archive_name.replace('.zip', '')
    extracted_path = f'{dir_path}/{dir_name}'

    with ZipFile(file=archive_path) as archive:
        archive.extractall(path=extracted_path)

    return extracted_path


def _extract_gz(dir_path: str, archive_name: str) -> str:
    archive_path = f'{dir_path}/{archive_name}'
    extracted_file_name = archive_name.replace('.gz', '')
    extracted_path = f'{dir_path}/{extracted_file_name}'

    with gzip.open(filename=archive_path, mode='rb') as archive:
        with open(file=extracted_path, mode='wb') as extracted_file:
            shutil.copyfileobj(archive, extracted_file)

    return extracted_path


def _validate_smod_serial_number(serial_number):
    """
    Validates SMOD serial number.
    :param serial_number: SMOD serial number
    :type serial_number: str
    """
    return bool(re.match(r'^[A-Z0-9]+$', serial_number))


@log_input_and_output
def check_if_directory_with_logs_exists(path):
    """
    Checks whether directory, from provided path exists
    :param path: absolute path i.e. '/home/ute/logs/'
    :type path: str
    :return: True if directory exists, False otherwise
    :rtype: bool
    """
    return os.path.exists(path)


@log_input_and_output
def check_if_directory_contains_files_with_extension(path, extension):
    """
    Checks whether directory from provided path contains files with given extension
    :param path: absolute path i.e. '/home/ute/logs/'
    :type path: str
    :param extension: extension of file i.e. '.LOG'
    :type extension: str
    :return: True if directory contains file/s with provided extension, False otherwise
    :rtype: bool
    """
    files_in_directory = os.listdir(path)
    for file in files_in_directory:
        if file.endswith(extension):
            return True
    return False


@log_input_and_output
def _is_file_existing(file_path):
    """
    Checks whether a file exists in a specific directory.
    :param file_path: absolute path to file
    :type file_path: str
    :return: True if a file exists in a specific directory or False when the file doesn't exist
    :rtype: bool
    """
    return os.path.isfile(file_path)


@log_input_and_output
def _is_file_empty(file_path):
    """
    Checks whether a file is empty.
    :param file_path: absolute path to file
    :type file_path: str
    :return: True if a file is empty, False otherwise
    :rtype: bool
    """
    return True if os.path.getsize(file_path) == 0 else False


@log_input_and_output
def _find_file_in_directory_by_regex(directory_path, filename_regex):
    """
    Gets file name of file located in given directory path by particular regex pattern name.
    :param directory_path: path to directory with file
    :type directory_path: str
    :param filename_regex: filename regex to find
    :type filename_regex: str(regex)
    :return: file name or None when filename not found
    :rtype: Union[str, None]
    """
    file_list = os.listdir(directory_path)
    for file in file_list:
        if re.fullmatch(filename_regex, file):
            return file


@log_input_and_output
def _verify_if_file_is_existing(file_path):
    """
    Verifies if a file exists in a specific directory.
    :param file_path: absolute path to file
    :type file_path: str
    :raises FileNotFoundError: if file does not exist
    """
    if not _is_file_existing(file_path=file_path):
        raise FileNotFoundError(f"File {file_path} does not exist.")


@log_input_and_output
def _create_dir_if_does_not_exist(dir_path):
    """
    Checks whether given directory exists and creates it if doesn't.

    :param dir_path: absolute path to directory which will be created, if it doesn't exist
    :type dir_path: str
    """
    os.makedirs(dir_path, exist_ok=True)


@log_input_and_output
def _get_dict_key_and_value_if_regex_matches_dict_value(dict_data, value_regex):
    """
    Gets dictionary key and value if value matches regex.
    Supports values being lists by checking each item in the list and returning the first item match.

    :param dict_data: dictionary to be searched
    :type dict_data: dict
    :param value_regex: regex for dictionary keys
    :type value_regex: str
    :return: key and value from given dictionary with matching regex
    :rtype: tuple(str, str) or None
    """
    for key, value in dict_data.items():
        if isinstance(value, list):
            for item in value:
                if re.search(value_regex, str(item)):
                    return key, item
        else:
            if re.search(value_regex, str(value)):
                return key, value
    return None
